const icons={
 bus:'<rect x="4" y="4" width="16" height="15" rx="3"/><path d="M4 11h16M8 4v7m8-7v7M7 19v2m10-2v2M7 15h1m8 0h1"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 users:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',
 school:'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-6h6v6M9 10h.01M15 10h.01"/>',
 absence:'<path d="M8 4H5v17h14V4h-3M9 3h6v4H9zM8 12h8M8 16h5"/>',
 route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v5a4 4 0 0 0 4 4h4a4 4 0 0 0 4-4V7M15 10l3-3 3 3"/>',
 file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 13h8M8 17h5"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 down:'<path d="m6 9 6 6 6-6"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 edit:'<path d="m14 5 5 5M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15z"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',
 logout:'<path d="M9 4H4v16h5m0-8h12m-4-4 4 4-4 4"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M4 15v6h16v-6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 wheel:'<circle cx="13" cy="4" r="2"/><path d="M12 7v6h6l3 6M12 9h5M9 11a5 5 0 1 0 7 7"/>',
 shield:'<path d="m12 3 8 3v5c0 5-8 10-8 10s-8-5-8-10V6zM8 12l3 3 5-6"/>'
};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'), modal=document.querySelector('#modal');
const days=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag'];
let renderedRevision, state, me, config, page='dashboard', selectedDate, direction='return', search='', schoolFilter='', reviewFilter=false, expanded=new Set(), preview, selectedDriver='', lastSync=Date.now(), loading=false;
const titles={dashboard:'Übersicht',tours:'Tourenplanung',students:'Schüler',schools:'Schulen',absences:'Abwesenheiten',fleet:'Fahrzeuge & Fahrer',io:'Import & Export'};
const initial=s=>s.split(/\s+/).map(p=>p[0]).slice(0,2).join('');
const school=id=>state.schools.find(s=>s.id===id), student=id=>state.students.find(s=>s.id===id), bus=id=>state.buses.find(b=>b.id===id), driver=id=>state.drivers.find(d=>d.id===id);
const dayIndex=d=>(new Date(d+'T12:00:00Z').getUTCDay()+6)%7;
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('de-DE',{day:'numeric',month:'long',year:'numeric'});
function addDate(d,n){return new Date(new Date(d+'T12:00:00Z').getTime()+n*86400000).toISOString().slice(0,10);}
function absent(s){return state.absences.some(a=>a.studentId===s.id&&a.from<=selectedDate&&a.to>=selectedDate&&(a.direction==='both'||a.direction===direction));}
function seatCount(t){return t.studentIds.reduce((n,id)=>n+(student(id)?.companion?2:1),0);}
function activeStudents(){const d=dayIndex(selectedDate);return d<5?state.students.filter(s=>s.active&&!s.needsReview&&s.schedule[d].enabled&&(direction==='return'||s.outboundEnabled!==false)&&school(s.schoolId)?.address):[];}
function toursToday(){return state.tours.filter(t=>t.date===selectedDate&&t.direction===direction).sort((a,b)=>a.time.localeCompare(b.time));}
function unplanned(){const assigned=new Set(toursToday().flatMap(t=>t.studentIds));return activeStudents().filter(s=>!absent(s)&&!assigned.has(s.id));}
function badge(t){const vals=Object.values(t.progress);return vals.every(v=>['done','skipped'].includes(v))?'<span class="pill grey">Abgeschlossen</span>':vals.some(v=>v==='onboard'||v==='done')?'<span class="pill green">Unterwegs</span>':!t.busId?'<span class="pill orange">Zuweisung offen</span>':'<span class="pill green">Geplant</span>';}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
async function api(path,method='GET',body,raw=false){const r=await fetch('/api'+path,{method,headers:{...(body&&!raw?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'If-Match':String(state?.revision??0)}:{})},body:body?(raw?body:JSON.stringify(body)):undefined});const data=await r.json();if(!r.ok){if(r.status===409)await refresh(true);if(r.status===401&&path!=='/login'){me=null;renderLogin();}throw new Error(data.error||'Anfrage fehlgeschlagen.');}return data;}
async function refresh(force=false){if(!me)return;try{const next=await api('/state');const changed=renderedRevision!==next.revision;state=next;lastSync=Date.now();if((changed||force)&&!modal.open&&!document.activeElement?.matches('input,select,textarea'))render();const live=document.querySelector('.live');if(live){live.textContent='Daten aktuell';live.title='Letzte Aktualisierung: '+new Date(lastSync).toLocaleTimeString('de-DE');}}catch(e){const live=document.querySelector('.live');if(live)live.textContent='Verbindung unterbrochen';if(force)toast(e.message,true);}}
const button=(text,action,ico='plus',cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${icon(ico)}${text}</button>`;
function renderLogin(){app.innerHTML=`<div class="login-page"><section class="login-hero"><div class="brand"><span class="brand-mark">${icon('bus')}</span><span>schulweg<span class="brand-dot">.</span></span></div><h1>Ein guter Schultag<br>beginnt mit einem<br><em>sicheren Weg.</em></h1><p>Schülerverkehr organisieren. Individuell planen. Gemeinsam zuverlässig ankommen.</p><div class="hero-route">${icon('pin')} Zuhause <span class="route-line"></span>${icon('school')} Schule</div><footer>FREIGESTELLTER SCHÜLERVERKEHR · BIS ZU 250 SCHÜLER</footer></section><section class="login-form-wrap"><div class="login-card"><div class="eyebrow">Willkommen bei Schulweg</div><h2>Alles auf einem Fahrplan.</h2><p>Dein Arbeitsplatz für die Disposition.<br>Für Fahrer steht ein eigener Zugang bereit.</p><form id="login-form" method="post"><label class="field">Benutzername<input name="username" autocomplete="username" required placeholder="admin oder fahrer1" value="${config.demoLogin?(location.pathname==='/fahrer'?'fahrer1':'admin'):''}"></label><label class="field">Passwort<input name="password" type="password" autocomplete="current-password" required placeholder="Passwort eingeben"></label><div class="login-error" role="alert"></div><button class="button" type="submit">Anmelden ${icon('arrow')}</button></form>${config.demoLogin?`<div class="demo-box"><strong>Die App kennenlernen</strong><br>Fiktive Beispieldaten, keine echten Schülerdaten.<br>${button(location.pathname==='/fahrer'?'Fahrer-Demo öffnen':'Demo öffnen','demo-login','arrow','secondary small')}<br><small>Admin: Schulweg-Demo! · Fahrer: Fahrer-Demo!</small></div>`:`<div class="demo-box">${icon('shield')} Geschützter Zugang zur Beförderungsplanung.</div>`}</div></section></div>`;}
function sidebar(){return `<aside class="sidebar"><a class="brand" href="/" aria-label="Schulweg Startseite"><span class="brand-mark">${icon('bus')}</span><span class="brand-text">schulweg.</span></a><div class="brand-sub">Gemeinsam unterwegs</div><nav><div class="nav-caption">Arbeitsplatz</div>${[['dashboard','grid'],['tours','route'],['students','users'],['schools','school'],['absences','absence'],['fleet','bus'],['io','file']].map(([id,ico])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}" title="${titles[id]}" aria-label="${titles[id]}">${icon(ico)}<span class="nav-label">${titles[id]}</span>${id==='students'?`<span class="nav-count">${state.students.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="driver-link" data-page="driver">${icon('bus')}<span>Fahreransicht öffnen</span>${icon('arrow')}</button><div class="sidebar-note">Individuelle Wege.<br>Ein gemeinsamer Plan.</div><div class="profile"><span class="avatar">DP</span><div><strong>Disposition</strong><small>${state.demo?'Demo-Arbeitsplatz':'Verwaltung'}</small></div><button class="logout" data-action="logout" title="Abmelden">${icon('logout')}</button></div></div></aside>`;}
function render(){renderedRevision=state?.revision;if(!me)return renderLogin();if(me.role==='driver'||page==='driver')return renderDriver();app.innerHTML=`<div class="app-shell">${sidebar()}<main class="main"><header class="topbar"><div class="breadcrumb">Arbeitsplatz ${icon('chevron')}<strong>${titles[page]}</strong></div><div class="top-actions"><span class="live">Daten aktuell</span>${state.demo?'<span class="pill orange">Demodaten</span>':''}<button class="icon-button" data-action="refresh" title="Daten aktualisieren">${icon('refresh')}</button><span class="avatar">DP</span></div></header><div class="content">${pageContent()}<div class="footnote"><span>Schulweg · Freigestellter Schülerverkehr</span><span>8 Fahrgäste je Bus · 5 Schultage · individuelle Beförderung</span></div></div></main></div>`;}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">Deine Disposition im Blick</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-buttons">${actions}</div></div>`;}
function pageContent(){switch(page){case'dashboard':return dashboard();case'tours':return pageHead('Jeder Schüler. Die passende Tour.','Schule, individuelle Zeiten und Fahrzeugkapazität zusammen planen.',button('Eigene Tour','tour-create','plus','secondary')+button('Touren zusammenstellen','plan','route'))+planner();case'students':return studentsPage();case'schools':return schoolsPage();case'absences':return absencesPage();case'fleet':return fleetPage();case'io':return ioPage();}}
function dashboard(){const present=activeStudents().filter(s=>!absent(s)).length,missing=state.students.filter(absent).length,tours=toursToday(),used=new Set(tours.map(t=>t.busId).filter(Boolean)).size;return pageHead('Guten Tag, Disposition.','Hier kommt alles zusammen – für einen gut geplanten Schultag.',button('Abwesenheit melden','absence','plus','secondary')+button('Touren zusammenstellen','plan','route'))+`<div class="metrics">${[[present,'Schüler unterwegs','users',`${state.students.length} Schüler insgesamt`],[tours.length,'Geplante Touren','route',`${direction==='return'?'Rückfahrten':'Hinfahrten'} am ausgewählten Tag`],[used,'Fahrzeuge im Einsatz','bus',`${state.buses.length} Kleinbusse im Fuhrpark`],[missing,'Abwesende Schüler','absence','In aktuellen Touren berücksichtigt']].map(([n,label,ico,sub])=>`<div class="metric"><div class="metric-top">${label}<span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${n}<span></span></div><div class="metric-bottom">${sub}</div></div>`).join('')}</div>${planner()}<div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>Heute nicht dabei</h2><p>Abwesenheiten am ${dateLabel(selectedDate)}</p></div><button class="text-link" data-page="absences">Alle ansehen ${icon('arrow')}</button></div>${state.absences.filter(a=>a.from<=selectedDate&&a.to>=selectedDate).slice(0,4).map(a=>`<div class="absent-row"><span class="initial">${esc(initial(student(a.studentId)?.name||'?'))}</span><div><strong>${esc(student(a.studentId)?.name)}</strong><small>${esc(school(student(a.studentId)?.schoolId)?.name)}</small></div><span class="pill red">${esc(a.reason)}</span></div>`).join('')||'<div class="empty">Keine Abwesenheiten gemeldet.</div>'}</section><section class="panel"><div class="panel-head"><h2>Individuell geplant. Sicher unterwegs.</h2>${icon('shield')}</div><div class="tip-card"><div class="tip-icon">${icon('route')}</div><div><h3>Ein Wochenplan für jedes Kind</h3><p>Von 11:20 bis 18:00 Uhr. Verschiedene Unterrichtszeiten, eigene Haltestellen und besondere Anforderungen bleiben im Blick.</p><p><strong>${state.students.filter(s=>s.wheelchair).length}</strong> Schüler mit Rollstuhlbedarf · <strong>${state.students.filter(s=>s.companion).length}</strong> mit Begleitperson</p><button class="text-link" data-page="students">Wochenpläne verwalten ${icon('arrow')}</button></div></div></section></div>`;}
function planner(){const monday=addDate(selectedDate,-dayIndex(selectedDate)),tours=toursToday(),pending=unplanned(),unassigned=tours.filter(t=>!t.busId).length,review=state.students.filter(s=>s.needsReview).length;return `<section class="panel"><div class="panel-head"><div><h2>Der Fahrplan für diese Woche</h2><p>${dateLabel(monday)} – ${dateLabel(addDate(monday,4))}</p></div><div class="planner-tools"><div class="segmented"><button data-direction="outbound" class="${direction==='outbound'?'active':''}">Hinfahrt</button><button data-direction="return" class="${direction==='return'?'active':''}">Rückfahrt</button></div><input type="date" class="date-input" id="date-select" value="${selectedDate}" aria-label="Planungsdatum"></div></div><div class="week-strip">${days.map((d,i)=>`<button class="day ${selectedDate===addDate(monday,i)?'selected':''}" data-date="${addDate(monday,i)}"><strong>${d}</strong>${new Date(addDate(monday,i)+'T12:00:00Z').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</button>`).join('')}</div><div class="planner-summary"><span><strong>${tours.length} Touren</strong> · ${activeStudents().filter(s=>!absent(s)).length} Schüler · ${dateLabel(selectedDate)}</span><div class="legend"><span><i class="dot"></i>Geplant</span><span><i class="dot amber"></i>Offene Zuweisung</span></div></div><div class="tour-list">${pending.length?`<div class="notice">${icon('info')}<span>${pending.length} Schüler ohne Tour. Bitte Touren zusammenstellen; vorhandene, noch nicht begonnene Touren dieser Richtung werden ersetzt.</span></div>`:''}${unassigned?`<div class="notice">${icon('info')}<span>${unassigned} Touren ohne verfügbares Fahrzeug oder Fahrer. Zeitfenster und Rollstuhlkapazität prüfen und zuweisen.</span></div>`:''}${review?`<div class="notice">${icon('info')}<span>${review} Schüler benötigen eine Datenprüfung und sind noch nicht für die automatische Planung freigegeben. <button class="text-link" data-action="review-students">Prüfen</button></span></div>`:''}${tours.map(tourCard).join('')||`<div class="empty">${icon('route')}Noch keine Touren für diesen Tag.<br>Individuelle Wochenzeiten prüfen und Touren zusammenstellen.</div>`}<div class="status-line">${icon('info')} Zeitfenster sind Schätzungen mit 10 Minuten Puffer. Disposition prüft Fahrzeiten und Haltestellen vor Fahrtfreigabe.</div></div></section>`;}
function tourCard(t){const s=school(t.schoolId),b=bus(t.busId),d=driver(t.driverId),count=seatCount(t);return `<article class="tour-card"><div class="tour-row"><div class="tour-time">${esc(t.time)}<small>${t.direction==='return'?'Ab Schule':'An Schule'}</small></div><div class="route-title"><span class="route-icon">${icon('school')}</span><div><strong>${esc(s?.name)}</strong><small>${esc([...new Set(t.studentIds.map(id=>student(id)?.district))].join(' · '))}</small></div></div><div class="tour-driver">${esc(d?.name||'Fahrer offen')}<small>${esc(b?.name||'Fahrzeug offen')} ${b?'· '+esc(b.plate):''}</small></div><div class="capacity"><strong>${count} / ${b?.capacity||8} Fahrgäste</strong><div class="seats">${Array.from({length:b?.capacity||8},(_,i)=>`<i class="seat ${i<count?'filled':''}"></i>`).join('')}</div></div>${badge(t)}<button class="expand" data-expand="${t.id}" title="Tourdetails anzeigen" aria-expanded="${expanded.has(t.id)}">${icon(expanded.has(t.id)?'down':'chevron')}</button></div>${expanded.has(t.id)?`<div class="tour-details"><header><div class="hint">${t.studentIds.length} Schüler · ${t.studentIds.filter(id=>student(id)?.companion).length} Begleitpersonen · ${t.studentIds.filter(id=>student(id)?.wheelchair).length} Rollstuhlplätze</div><div class="head-buttons">${button('Zuweisung','assignment','edit','secondary small',`data-id="${t.id}"`)}${button('Schüler zuordnen','move','users','secondary small',`data-id="${t.id}"`)}</div></header><div class="children-grid">${t.studentIds.map(id=>{const p=student(id);return `<div class="child-chip"><span class="initial">${esc(initial(p.name))}</span><div><strong>${esc(p.name)} ${p.wheelchair?icon('wheel'):''}</strong><small>${esc(stopAddress(p,t))}</small><small>${p.companion?'Mit Begleitperson · ':''}${esc(statusText(t.progress[id]))}</small></div></div>`;}).join('')}</div></div>`:''}</article>`;}
function statusText(s){return {waiting:'Wartet',onboard:'An Bord',done:'Angekommen',skipped:'Nicht erschienen'}[s]||s;}
function stopAddress(s,t){const plan=s.schedule[dayIndex(t.date)];return (t.direction==='return'?plan?.returnAddress:plan?.pickupAddress)||s.address;}
function studentsPage(){let pupils=state.students.filter(s=>(!search||`${s.name} ${s.address} ${s.district}`.toLowerCase().includes(search.toLowerCase()))&&(!schoolFilter||s.schoolId===schoolFilter)&&(!reviewFilter||s.needsReview));return pageHead('Jeder Weg ist persönlich.','Schülerdaten, besondere Anforderungen und individuelle Wochenzeiten.',button('Daten importieren','to-io','upload','secondary')+button('Schüler hinzufügen','student','plus'))+`<section class="panel"><div class="filters"><label class="search">${icon('search')}<input id="search-students" placeholder="Schüler, Adresse oder Wohngebiet suchen …" value="${esc(search)}" aria-label="Schüler suchen"></label><select id="school-filter" aria-label="Schule filtern"><option value="">Alle Schulen</option>${state.schools.map(s=>`<option value="${s.id}" ${schoolFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><label class="checkbox"><input type="checkbox" id="review-filter" ${reviewFilter?'checked':''}>Nur Prüfbedarf</label></div><div class="table-wrap"><table><thead><tr><th>Schüler</th><th>Schule / Wohngebiet</th><th>Rückfahrt Mo–Fr</th><th>Beförderung</th><th></th></tr></thead><tbody>${pupils.map(s=>`<tr><td><div class="student-name"><span class="initial">${esc(initial(s.name))}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.address)}</small></div></div></td><td>${esc(school(s.schoolId)?.name)}<small>${esc(s.district)}</small></td><td>${s.schedule.map(d=>d.enabled?esc(d.end):'–').join(' · ')}<small>${s.morningPickup?'Morgen-Abholung: '+esc(s.morningPickup):s.outboundEnabled!==false?'Hinfahrt ab Wohnadresse':'Nur Rückfahrten freigegeben'}</small></td><td>${s.needsReview?'<span class="pill orange">Daten prüfen</span>':!s.active?'<span class="pill grey">Inaktiv</span>':absent(s)?'<span class="pill red">Abwesend</span>':'<span class="pill green">Aktiv</span>'}<small>${s.wheelchair?'Rollstuhl · ':''}${s.companion?'Begleitperson':''}</small></td><td><button class="icon-button" data-action="student" data-id="${s.id}" title="Schüler bearbeiten">${icon('edit')}</button><button class="icon-button" data-action="absence" data-id="${s.id}" title="Abwesenheit melden">${icon('absence')}</button></td></tr>`).join('')}</tbody></table></div>${!pupils.length?'<div class="empty">Keine passenden Schüler gefunden.</div>':''}<div class="table-footer">${pupils.length} von ${state.students.length} Schülern · ausgelegt für bis zu 250</div></section>`;}
function schoolsPage(){return pageHead('Ein Plan für alle Schulen.','Schulstandorte und Adressen für eine zuverlässige Beförderung.',button('Schule hinzufügen','school','plus'))+`<div class="cards-grid">${state.schools.map(s=>`<article class="school-card"><div class="school-icon">${icon('school')}</div><h3>${esc(s.name)}</h3><p>${esc(s.address||'Adresse fehlt – vor Tourenplanung ergänzen')}</p><footer><span>${state.students.filter(p=>p.schoolId===s.id).length} Schüler</span><button class="text-link" data-action="school" data-id="${s.id}">Bearbeiten ${icon('edit')}</button></footer></article>`).join('')}</div><p class="hint">${state.schools.length} Schulstandorte · Mehr als 15 Standorte werden für zusätzliche Einträge im Schulverzeichnis ebenfalls unterstützt.</p>`;}
function absencesPage(){return pageHead('Heute ohne Fahrt.','Krankmeldungen und andere Abwesenheiten direkt in der Planung berücksichtigen.',button('Abwesenheit melden','absence','plus'))+`<div class="notice info">${icon('info')}<span>Neue Abwesenheiten entfernen wartende Schüler sofort aus passenden Touren. Nach einer Rücknahme bitte Touren neu zusammenstellen oder den Schüler wieder zuordnen.</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Schüler</th><th>Zeitraum</th><th>Fahrt</th><th>Grund</th><th></th></tr></thead><tbody>${[...state.absences].sort((a,b)=>b.from.localeCompare(a.from)).map(a=>`<tr><td><strong>${esc(student(a.studentId)?.name)}</strong><small>${esc(school(student(a.studentId)?.schoolId)?.name)}</small></td><td>${dateLabel(a.from)}<small>bis ${dateLabel(a.to)}</small></td><td>${{both:'Hin- & Rückfahrt',outbound:'Hinfahrt',return:'Rückfahrt'}[a.direction]}</td><td><span class="pill red">${esc(a.reason)}</span></td><td><button class="text-link" data-action="remove-absence" data-id="${a.id}">Zurücknehmen</button></td></tr>`).join('')}</tbody></table></div>${!state.absences.length?'<div class="empty">Keine Abwesenheiten hinterlegt.</div>':''}</section>`;}
function fleetPage(){return pageHead('Bereit für den nächsten Schultag.','Kleinbusse mit höchstens acht Fahrgästen, Rollstuhlplätzen und Fahrerzuordnung.',button('Fahrer hinzufügen','driver','plus','secondary')+button('Fahrzeug hinzufügen','bus','plus'))+`<section class="panel"><div class="panel-head"><h2>Fuhrpark</h2><span class="pill green">${state.buses.length} Fahrzeuge</span></div><div class="table-wrap"><table><thead><tr><th>Fahrzeug</th><th>Kennzeichen</th><th>Fahrgäste gesamt</th><th>Rollstuhlplätze</th><th>Status</th><th></th></tr></thead><tbody>${state.buses.map(b=>`<tr><td><div class="student-name"><span class="initial">${icon('bus')}</span><strong>${esc(b.name)}</strong></div></td><td>${esc(b.plate)}</td><td>${b.capacity} einschließlich Begleitpersonen</td><td>${b.wheelchairSpaces?b.wheelchairSpaces+' Rollstuhlplatz'+(b.wheelchairSpaces>1?'e':''):'Keine'}</td><td><span class="pill ${b.active?'green':'grey'}">${b.active?'Verfügbar':'Inaktiv'}</span></td><td><button class="icon-button" data-action="bus" data-id="${b.id}" title="Fahrzeug bearbeiten">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Fahrer & Zugänge</h2><p>Fahrer sehen ausschließlich ihre zugewiesenen Touren.</p></div><div class="table-wrap"><table><thead><tr><th>Fahrer</th><th>Benutzername</th><th>Touren am ausgewählten Tag</th><th>Status</th><th></th></tr></thead><tbody>${state.drivers.map(d=>`<tr><td><strong>${esc(d.name)}</strong></td><td>${esc(d.username)}</td><td>${toursToday().filter(t=>t.driverId===d.id).length}</td><td><span class="pill ${d.active?'green':'grey'}">${d.active?'Aktiv':'Inaktiv'}</span></td><td><button class="icon-button" data-action="driver" data-id="${d.id}" title="Fahrer bearbeiten">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer">Fahrerpasswort wird am Server konfiguriert. Fahrerportal: /fahrer</div></section>`;}
function ioPage(){return pageHead('Daten rein. Fahrplan raus.','Excel, CSV und JSON – mit Vorschau und Prüfung vor jeder Übernahme.')+`<div class="io-grid"><section class="panel"><div class="panel-head"><h2>Schülerdaten importieren</h2>${icon('upload')}</div><div class="panel-body"><p class="hint">Unterstützt die hochgeladene Schülerübersicht sowie Schulweg-Exporte. Excel und CSV übernehmen Schüler und Wochenpläne; JSON stellt ein vollständiges Backup wieder her.</p>${config.providedImport?`<div class="notice info">${icon('file')}<span>Deine hochgeladene Schülerübersicht ist bereitgestellt.<br>${button('Übersicht prüfen','provided-import','file','secondary small')}</span></div>`:''}<div class="dropzone">${icon('file')}<strong>Deine Schülerübersicht</strong><p>Excel (.xlsx), CSV oder JSON · maximal 8 MB<br>Eine Vorschau erscheint vor dem Import.</p><input type="file" id="import-file" accept=".xlsx,.csv,.json" class="hidden"><label for="import-file" class="button secondary">${icon('upload')} Datei auswählen</label></div><label class="field">Tabellenblätter bei der vorhandenen Schülerübersicht<select id="import-sheet"><option value="50">Beide Schülerblätter, Dubletten prüfen</option><option value="0">Nur erstes Schülerblatt</option><option value="1">Nur zweites Schülerblatt</option></select></label><p class="hint">Spalte L: morgendliche Abholzeit. Q / V / AA / AF / AK: Rückfahrt ab Schule. Tageshaltestellen werden erhalten. Nicht eindeutige Zeiten bleiben gesperrt, bis sie geprüft sind.</p>${!config.secureConfig?`<div class="notice">${icon('shield')}<span>Die Vorschau funktioniert bereits. Zum Speichern von Echtdaten zuerst eigene Zugangspasswörter einrichten. <button class="text-link" data-action="security">Zugänge einrichten</button></span></div>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Export & Datensicherung</h2>${icon('download')}</div><div class="panel-body">${[['xlsx','Excel-Arbeitsmappe','Schüler, Schulen, Wochenpläne, Abwesenheiten, Touren und Fuhrpark.'],['csv','Schüler als CSV','Alle Schüler mit fünf Tagesplänen. Kompatibel mit Excel und LibreOffice.'],['json','Vollständiges Backup','Alle Daten und Zuordnungen für eine vollständige Wiederherstellung.']].map(([format,title,desc])=>`<div class="export-option"><div><strong>${title}</strong><small>${desc}</small></div><a class="button secondary small" href="/api/export?format=${format}" download>${icon('download')}${format.toUpperCase()}</a></div>`).join('')}<div class="notice info">${icon('info')}<span>Exportierte Dateien enthalten personenbezogene Daten. Nur an berechtigte Personen weitergeben und geschützt aufbewahren.</span></div><p class="hint">Tipp: Der Excel-Export dient auch als Importvorlage. CSV verwendet Semikolon und UTF-8. Ein JSON-Backup ersetzt nach Bestätigung die vorhandenen Daten.</p></div></section></div>`;}
function showModal(title,content,action,submit='Speichern'){modal.innerHTML=`<form id="modal-form" method="post" data-submit="${action}"><header class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close-modal" title="Schließen">${icon('close')}</button></header><div class="modal-body">${content}</div><div class="form-error" role="alert"></div><footer class="modal-footer"><button type="button" class="button secondary" data-action="close-modal">Abbrechen</button><button class="button" type="submit">${icon('check')}${submit}</button></footer></form>`;modal.showModal();}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function schoolOptions(value){return state.schools.map(s=>`<option value="${s.id}" ${s.id===value?'selected':''}>${esc(s.name)}</option>`).join('');}
function studentModal(id){const s=student(id)||{schedule:days.map(()=>({enabled:true,start:'08:00',end:'13:00'})),active:true,outboundEnabled:true};showModal(id?'Schüler & Wochenplan bearbeiten':'Schüler hinzufügen',`<input type="hidden" name="id" value="${id||''}">${s.importWarnings?.length?`<div class="notice">${icon('info')}<span>${s.importWarnings.map(esc).join('<br>')}<br>Quelle: Schülerblatt ${s.source?.sheet||'–'}, Zeile ${s.source?.row||'–'}</span></div>`:''}<div class="form-grid">${field('Vor- und Nachname','name',s.name,'text','required maxlength="150"')}${field('Wohngebiet / Ort','district',s.district,'text','required maxlength="80"')}<label class="field full">Wohnadresse<input name="address" value="${esc(s.address)}" required maxlength="240" placeholder="Straße, Hausnummer, PLZ Ort"></label><label class="field">Schule<select name="schoolId" required>${schoolOptions(s.schoolId)}</select></label>${field('Kontakt der Bezugsperson','contact',s.contact)}<label class="field full">Hinweise für die Beförderung<textarea name="notes" maxlength="1000">${esc(s.notes)}</textarea></label>${field('Morgendliche Abholzeit (Quellangabe)','morningPickup',s.morningPickup)}</div><div class="checks"><label class="checkbox"><input type="checkbox" name="active" ${s.active?'checked':''}>Aktiv</label><label class="checkbox"><input type="checkbox" name="wheelchair" ${s.wheelchair?'checked':''}>Rollstuhlplatz</label><label class="checkbox"><input type="checkbox" name="companion" ${s.companion?'checked':''}>Eine Begleitperson</label><label class="checkbox"><input type="checkbox" name="outboundEnabled" ${s.outboundEnabled!==false?'checked':''}>Hinfahrten freigeben</label></div><div class="form-section">Individueller Wochenplan</div><p class="hint">Beginn = Ankunft an der Schule. Ende = Abholung an der Schule (11:20–18:00 Uhr). Haltestelle bleibt leer, wenn die Wohnadresse gilt.</p><div class="table-wrap"><table class="schedule"><thead><tr><th>Tag</th><th>Fahrt</th><th>Abholung früh</th><th>Schulbeginn</th><th>Ab Schule</th><th>Morgenhaltestelle</th><th>Rückfahrt-Ziel</th></tr></thead><tbody>${days.map((d,i)=>`<tr><td>${d.slice(0,2)}</td><td><input type="checkbox" name="enabled${i}" ${s.schedule[i].enabled?'checked':''} aria-label="${d} befördern"></td><td><input type="time" name="pickup${i}" value="${s.schedule[i].pickupTime||''}" min="05:00" max="10:59" aria-label="${d} Morgen-Abholung"></td><td><input type="time" name="start${i}" value="${s.schedule[i].start}" min="06:00" max="11:00" required aria-label="${d} Schulbeginn"></td><td><input type="time" name="end${i}" value="${s.schedule[i].end}" min="11:20" max="18:00" required aria-label="${d} Rückfahrt"></td><td><input type="text" name="morningstop${i}" value="${esc(s.schedule[i].pickupAddress)}" placeholder="Wohnadresse" aria-label="${d} Morgenhaltestelle"></td><td><input type="text" name="stop${i}" value="${esc(s.schedule[i].returnAddress)}" placeholder="Wohnadresse" aria-label="${d} Rückfahrtziel"></td></tr>`).join('')}</tbody></table></div>${s.needsReview?'<div class="checks"><label class="checkbox"><input type="checkbox" name="reviewed">Schule, Zeiten, Haltestellen und besondere Anforderungen geprüft – Planung freigeben</label></div>':''}`,'student');}
function absenceModal(id){showModal('Abwesenheit melden',`<div class="notice info">${icon('info')}<span>Wartende Schüler werden sofort aus betroffenen Touren entfernt. Änderungen erreichen die Fahrer beim nächsten Datenabgleich.</span></div><div class="form-grid"><label class="field full">Schüler<select name="studentId" required>${[...state.students].sort((a,b)=>a.name.localeCompare(b.name,'de')).map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${field('Von','from',selectedDate,'date','required')}${field('Bis einschließlich','to',selectedDate,'date','required')}<label class="field">Fahrtrichtung<select name="direction"><option value="both">Hin- und Rückfahrt</option><option value="return">Nur Rückfahrt</option><option value="outbound">Nur Hinfahrt</option></select></label><label class="field">Grund<select name="reason"><option>Krankmeldung</option><option>Private Beförderung</option><option>Termin</option><option>Sonstige Abwesenheit</option></select></label></div>`,'absence','Abwesenheit übernehmen');}
function assignmentModal(id){const t=state.tours.find(t=>t.id===id);showModal('Fahrzeug & Fahrer zuweisen',`<input type="hidden" name="tourId" value="${id}"><p class="hint">${esc(school(t.schoolId)?.name)} · ${t.time} Uhr · ${seatCount(t)} Fahrgäste. Die Zuweisung prüft Kapazität, Rollstuhlplätze und Zeitüberschneidungen.</p><div class="form-grid"><label class="field">Fahrzeug<select name="busId" required>${state.buses.filter(b=>b.active).map(b=>`<option value="${b.id}" ${b.id===t.busId?'selected':''}>${esc(b.name)} · ${b.capacity} Plätze · ${b.wheelchairSpaces} Rollstuhl</option>`).join('')}</select></label><label class="field">Fahrer<select name="driverId" required>${state.drivers.filter(d=>d.active).map(d=>`<option value="${d.id}" ${d.id===t.driverId?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label></div>`,'assignment');}
function moveModal(id){const t=state.tours.find(t=>t.id===id),day=dayIndex(t.date);const pupils=activeStudents().filter(s=>s.schoolId===t.schoolId&&(t.direction==='return'?s.schedule[day].end:s.schedule[day].start)===t.time&&!t.studentIds.includes(s.id)&&!absent(s));showModal('Tourenzusammenstellung anpassen',`<input type="hidden" name="tourId" value="${id}"><p class="hint">Schüler mit derselben Schule und Zeit in diese Tour verschieben. Die Kapazität bleibt auf acht Fahrgäste einschließlich Begleitpersonen begrenzt.</p><label class="field">Passender Schüler<select name="studentId" required><option value="">Bitte wählen</option>${pupils.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.district)}</option>`).join('')}</select></label>${!pupils.length?'<p class="hint">Keine weiteren passenden Schüler für diese Tour vorhanden.</p>':''}`,'move','Schüler zuordnen');}
function customTourChildren(){const form=document.querySelector('#modal-form'),sid=form.elements.schoolId.value,time=form.elements.time.value,day=dayIndex(selectedDate);const pupils=activeStudents().filter(s=>s.schoolId===sid&&(direction==='return'?s.schedule[day].end:s.schedule[day].start)===time&&!absent(s));document.querySelector('#custom-tour-children').innerHTML=pupils.map(s=>`<label class="checkbox"><input type="checkbox" name="studentIds" value="${s.id}">${esc(s.name)} · ${esc(s.district)}${s.companion?' · + Begleitperson':''}${s.wheelchair?' · Rollstuhl':''}</label>`).join('')||'<p class="hint">Keine passenden Schüler. Individuelle Zeit und Schule prüfen.</p>';}
function customTourModal(){showModal('Eigene Tour zusammenstellen',`<p class="hint">${dateLabel(selectedDate)} · ${direction==='return'?'Rückfahrt':'Hinfahrt'}. Gewählte Schüler werden aus noch nicht begonnenen Touren in die neue Tour verschoben. Fahrzeug und Fahrer anschließend in den Tourdetails zuweisen.</p><div class="form-grid"><label class="field">Schule<select name="schoolId" id="custom-school">${schoolOptions()}</select></label>${field(direction==='return'?'Abholzeit an der Schule':'Ankunft an der Schule','time',direction==='return'?'13:10':'08:00','time','required id="custom-time"')}</div><div class="form-section">Fahrgäste auswählen · maximal 8 inkl. Begleitpersonen</div><div id="custom-tour-children" class="form-grid"></div>`,'tour-create','Tour anlegen');customTourChildren();}
function previewModal(){showModal(preview.type==='backup'?'Backup wiederherstellen':'Importvorschau',`<div class="preview-stats">${[[preview.students.length,'Schüler'],[preview.schools.length,'Schulen'],[preview.reviewCount||0,'Zur Prüfung']].map(([n,label])=>`<div class="metric"><div class="metric-top">${label}</div><div class="metric-value">${n}</div></div>`).join('')}</div>${preview.warnings.map(w=>`<div class="notice">${icon('info')}<span>${esc(w)}</span></div>`).join('')}${preview.type!=='backup'&&preview.schools.some(s=>!s.address)?`<div class="form-section">Offene Schulzuordnungen</div><p class="hint">Abgekürzte Schulnamen mit dem Schulverzeichnis verbinden. Ohne Zuordnung bleiben betroffene Schüler zur Prüfung gesperrt.</p><div class="form-grid">${preview.schools.filter(s=>!s.address).map(s=>`<label class="field">${esc(s.name)}<select name="mapping:${esc(s.key)}"><option value="">Später manuell prüfen</option>${(preview.schoolDirectory||[]).map(d=>`<option value="${esc(d.key)}">${esc(d.name)}</option>`).join('')}</select></label>`).join('')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>Schüler</th><th>Prüfung</th></tr></thead><tbody>${preview.students.slice(0,8).map(s=>`<tr><td>${esc(s.name)}</td><td>${s.needsReview?'Erforderlich':'Zeiten erkannt'}</td></tr>`).join('')}</tbody></table></div><p class="hint">${preview.type==='backup'?'Alle vorhandenen Daten werden ersetzt.':state.demo?'Beim ersten Echtdatenimport werden fiktive Schüler, Schulen und Touren entfernt. Demo-Fahrzeuge und Fahrer bleiben zur weiteren Konfiguration erhalten.':'Vorhandene Schüler werden anhand von Name und Wohnadresse abgeglichen. Abweichende Dubletten zuerst prüfen.'}</p><label class="checkbox"><input name="confirm" type="checkbox" required>Ich habe die Vorschau geprüft und bestätige die Datenübernahme.</label>${!config.secureConfig?'<div class="notice">Eigene Serverpasswörter sind zum Speichern von Echtdaten erforderlich.</div>':''}`,'import',preview.type==='backup'?'Wiederherstellen':'Daten importieren');}
function navigationLink(addresses){const valid=addresses.filter(Boolean);if(!valid.length)return null;const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('destination',valid.at(-1));u.searchParams.set('travelmode','driving');if(valid.length>1)u.searchParams.set('waypoints',valid.slice(0,-1).slice(0,3).join('|'));return u.href;}
function renderDriver(){const isAdmin=me.role==='admin';if(!selectedDriver)selectedDriver=me.driverId||state.drivers[0]?.id;const tours=state.tours.filter(t=>t.driverId===selectedDriver&&t.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time));const name=driver(selectedDriver)?.name||me.name;app.innerHTML=`<header class="driver-top"><div class="brand"><span class="brand-mark">${icon('bus')}</span><span>schulweg.</span></div><div class="head-buttons">${isAdmin?button('Disposition','back-admin','arrow','secondary small'):''}<button class="icon-button" data-action="logout" title="Abmelden">${icon('logout')}</button></div></header><main class="driver-shell">${isAdmin?`<div class="notice">${icon('info')}<span>Fahreransicht als Vorschau. Ein Fahrerzugang zeigt ausschließlich zugewiesene Touren.</span></div>`:''}<div class="driver-header"><div><div class="eyebrow">Dein Fahrplan</div><h1>Gute Fahrt, ${esc(name.split(' ')[0])}.</h1><p class="subtitle">${tours.length} Touren · ${dateLabel(selectedDate)}</p></div><span class="live">Daten aktuell</span></div><div class="driver-toolbar"><input type="date" class="date-input" id="date-select" value="${selectedDate}" aria-label="Fahrtdatum">${isAdmin?`<select id="driver-select" aria-label="Fahrer wählen">${state.drivers.map(d=>`<option value="${d.id}" ${selectedDriver===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select>`:''}${button('Aktualisieren','refresh','refresh','secondary small')}</div>${tours.map(driverTour).join('')||`<div class="panel empty">${icon('bus')}Keine zugewiesenen Touren für diesen Tag.</div>`}<p class="hint">Automatischer Datenabgleich alle 5 Sekunden bei aktiver Verbindung. Bei Verbindungsabbruch vor Fahrtbeginn telefonisch mit der Disposition abstimmen.</p></main>`;}
function driverTour(t){const pupils=t.studentIds.map(student).filter(Boolean),pending=pupils.filter(s=>!['done','skipped'].includes(t.progress[s.id])),needSchool=t.direction==='return'?pending.some(s=>t.progress[s.id]==='waiting'):pending.length===0&&pupils.some(s=>t.progress[s.id]==='onboard');let addresses;if(t.direction==='return'){addresses=[...(needSchool?[school(t.schoolId)?.address]:[]),...pending.map(s=>stopAddress(s,t))];}else{addresses=pending.length?[...pending.filter(s=>t.progress[s.id]==='waiting').map(s=>stopAddress(s,t)),school(t.schoolId)?.address]:[];}const nav=navigationLink(addresses.slice(0,4));return `<article class="driver-tour"><header class="driver-tour-head"><div><span class="tour-time">${t.time}<small>${t.direction==='return'?'Abholung an der Schule':'Ankunft an der Schule'}</small></span><h2>${esc(school(t.schoolId)?.name)}</h2><p class="subtitle">${esc(bus(t.busId)?.name)} · ${esc(bus(t.busId)?.plate)} · ${seatCount(t)} Fahrgäste</p></div>${badge(t)}</header><div class="driver-route"><p class="hint">${icon('school')} ${esc(school(t.schoolId)?.address)}</p>${nav?`<a class="button" href="${esc(nav)}" target="_blank" rel="noopener noreferrer">${icon('pin')}Navigation starten</a>`:'<p class="hint">Tour abgeschlossen oder Adresse fehlt.</p>'}<p class="hint">Die nächsten bis zu vier Halte in Google Maps öffnen. Nach jedem Halt neu starten. Dabei werden die Zieladressen an Google übermittelt.</p></div>${pupils.map((s,i)=>`<div class="driver-stop"><span class="stop-number">${i+1}</span><div class="stop-details"><strong>${esc(s.name)}</strong>${s.wheelchair?` <span class="pill orange">${icon('wheel')}Rollstuhl</span>`:''}<p>${t.direction==='outbound'&&s.schedule[dayIndex(t.date)].pickupTime?'<strong>'+esc(s.schedule[dayIndex(t.date)].pickupTime)+' Uhr · Abholung</strong><br>':''}${esc(stopAddress(s,t))}${s.companion?'<br>Mit einer Begleitperson':''}</p>${s.notes?`<div class="driver-warning">${esc(s.notes)}</div>`:''}<div class="stop-actions"><span class="pill ${t.progress[s.id]==='done'?'green':'grey'}">${esc(statusText(t.progress[s.id]))}</span>${t.progress[s.id]==='waiting'?`${button('Eingestiegen','progress','check','small',`data-tour="${t.id}" data-student="${s.id}" data-status="onboard"`)}${button('Nicht erschienen','progress','close','secondary small',`data-tour="${t.id}" data-student="${s.id}" data-status="skipped"`)}`:t.progress[s.id]==='onboard'?button('Sicher angekommen','progress','check','small',`data-tour="${t.id}" data-student="${s.id}" data-status="done"`):t.progress[s.id]==='skipped'?button('Wieder aufnehmen','progress','refresh','secondary small',`data-tour="${t.id}" data-student="${s.id}" data-status="waiting"`):''}</div></div></div>`).join('')}</article>`;}

document.addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-page],[data-direction],[data-date],[data-expand]');if(!target)return;try{
 if(target.dataset.page){page=target.dataset.page;search='';schoolFilter='';reviewFilter=false;render();window.scrollTo(0,0);return;}
 if(target.dataset.direction){direction=target.dataset.direction;render();return;}
 if(target.dataset.date){selectedDate=target.dataset.date;render();return;}
 if(target.dataset.expand){const id=target.dataset.expand;expanded.has(id)?expanded.delete(id):expanded.add(id);render();return;}
 const {action,id}=target.dataset;
 if(action==='close-modal'){modal.close();return;}
 if(action==='student')return studentModal(id);
 if(action==='absence')return absenceModal(id);
 if(action==='tour-create')return customTourModal();
 if(action==='assignment')return assignmentModal(id);
 if(action==='move')return moveModal(id);
 if(action==='school'){const s=school(id)||{};return showModal(id?'Schule bearbeiten':'Schule hinzufügen',`<input type="hidden" name="id" value="${id||''}"><div class="form-grid">${field('Schulname','name',s.name,'text','required')}${field('Adresse mit PLZ und Ort','address',s.address,'text','required')}</div>`,'school');}
 if(action==='bus'){const b=bus(id)||{capacity:8,wheelchairSpaces:0,active:true};return showModal(id?'Kleinbus bearbeiten':'Kleinbus hinzufügen',`<input type="hidden" name="id" value="${id||''}"><div class="form-grid">${field('Fahrzeugname','name',b.name,'text','required')}${field('Kennzeichen','plate',b.plate,'text','required')}${field('Fahrgäste insgesamt','capacity',b.capacity,'number','min="1" max="8" required')}${field('Davon Rollstuhlplätze','wheelchairSpaces',b.wheelchairSpaces,'number','min="0" max="8" required')}</div><div class="checks"><label class="checkbox"><input type="checkbox" name="active" ${b.active?'checked':''}>Für Planung verfügbar</label></div><p class="hint">Begleitpersonen zählen als Fahrgäste. Die Gesamtkapazität muss zur tatsächlichen Fahrzeugkonfiguration passen. Deaktivierung löst noch nicht begonnene Zuweisungen.</p>`,'bus');}
 if(action==='driver'){const d=driver(id)||{active:true};return showModal(id?'Fahrer bearbeiten':'Fahrer hinzufügen',`<input type="hidden" name="id" value="${id||''}"><div class="form-grid">${field('Vor- und Nachname','name',d.name,'text','required')}${field('Benutzername','username',d.username,'text','required pattern="[a-z0-9._-]+"')}</div><div class="checks"><label class="checkbox"><input type="checkbox" name="active" ${d.active?'checked':''}>Fahrer aktiv</label></div><p class="hint">Anmeldung mit diesem Benutzernamen und dem am Server konfigurierten Fahrerpasswort. Deaktivierung sperrt den Zugang und löst noch nicht begonnene Zuweisungen.</p>`,'driver');}
 if(action==='security')return showModal('Zugänge für Echtdaten einrichten',`<p class="hint">Bitte unterschiedliche Passwörter mit jeweils mindestens 12 Zeichen wählen. Sie werden ausschließlich als gesalzene Hashes gespeichert. Die Demo-Zugänge werden deaktiviert. Fahrer melden sich mit ihrem individuellen Benutzernamen und dem gemeinsamen Fahrerpasswort an.</p><div class="form-grid">${field('Passwort Disposition','adminPassword','','password','required minlength="12" autocomplete="new-password"')}${field('Passwort Fahrerzugänge','driverPassword','','password','required minlength="12" autocomplete="new-password"')}</div>`,'security','Zugänge einrichten');
 if(action==='provided-import'){if(!config.secureConfig){toast('Bitte zuerst eigene Zugänge einrichten.',true);return;}preview=await api('/import/provided');return previewModal();}
 if(action==='to-io'){page='io';render();return;}
 if(action==='review-students'){page='students';reviewFilter=true;render();return;}
 if(action==='back-admin'){page='dashboard';render();return;}
 if(action==='demo-login'){const role=location.pathname==='/fahrer'?'driver':'admin';me=await api('/login','POST',{username:role==='admin'?'admin':'fahrer1',password:role==='admin'?'Schulweg-Demo!':'Fahrer-Demo!'});await refresh(true);return;}
 if(action==='logout'){await api('/logout','POST',{});me=null;state=null;renderLogin();return;}
 if(action==='refresh'){await refresh(true);toast('Daten aktualisiert');return;}
 if(action==='plan')return showModal('Touren zusammenstellen',`<p class="hint">${dateLabel(selectedDate)} · ${direction==='return'?'Rückfahrten ab Schule':'Hinfahrten zur Schule'}</p><div class="notice info">${icon('route')}<span>Gleiche Schule und Zeit werden zusammengefasst, nach Wohngebiet sortiert und auf geeignete Fahrzeuge verteilt. Acht Fahrgäste inklusive Begleitpersonen, Rollstuhlplätze und Zeitüberschneidungen werden geprüft.</span></div><p class="hint">Bestehende, noch nicht begonnene Touren dieser Richtung werden ersetzt. Die Planung ist eine Dispositionshilfe; reale Fahrzeiten müssen vor Fahrtbeginn geprüft werden.</p>`,'plan','Zusammenstellen');
 if(action==='remove-absence')return showModal('Abwesenheit zurücknehmen',`<input type="hidden" name="id" value="${id}"><p class="hint">Der Schüler ist danach wieder zur Beförderung vorgesehen. Bitte neu planen oder einer bestehenden Tour zuordnen.</p>`,'remove-absence','Zurücknehmen');
 if(action==='progress'){target.disabled=true;await api('/tours/progress','POST',{tourId:target.dataset.tour,studentId:target.dataset.student,status:target.dataset.status});await refresh(true);toast('Fahrgaststatus aktualisiert');return;}
 }catch(error){toast(error.message,true);target.disabled=false;}
});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='custom-school'||el.id==='custom-time'){customTourChildren();return;}if(el.id==='date-select'){if(!el.value)return;selectedDate=el.value;render();}if(el.id==='school-filter'){schoolFilter=el.value;render();}if(el.id==='review-filter'){reviewFilter=el.checked;render();}if(el.id==='driver-select'){selectedDriver=el.value;render();}if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>8*1024*1024){toast('Datei darf höchstens 8 MB groß sein.',true);el.value='';return;}try{const format=file.name.split('.').at(-1).toLowerCase(), sheet=document.querySelector('#import-sheet').value;toast('Datei wird geprüft …');preview=await api(`/import/preview?format=${format}&sheet=${sheet}`,'POST',await file.arrayBuffer(),true);previewModal();}catch(error){toast(error.message,true);}el.value='';}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search-students'){search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;render();const input=document.querySelector('#search-students');input.focus();input.setSelectionRange(pos,pos);},180);}});
document.addEventListener('submit',async e=>{if(!['login-form','modal-form'].includes(e.target.getAttribute('id')))return;e.preventDefault();const form=e.target,data=new FormData(form),values=Object.fromEntries(data),submit=form.querySelector('[type=submit]');submit.disabled=true;const errorEl=form.querySelector('.form-error,.login-error');errorEl.textContent='';try{
 if(form.getAttribute('id')==='login-form'){me=await api('/login','POST',values);await refresh(true);return;}
 const action=form.dataset.submit;let message='Änderungen gespeichert';
 if(action==='student'){const current=student(values.id);const record={...values,active:data.has('active'),wheelchair:data.has('wheelchair'),companion:data.has('companion'),outboundEnabled:data.has('outboundEnabled'),needsReview:current?.needsReview&&!data.has('reviewed'),schedule:days.map((_,i)=>({enabled:data.has(`enabled${i}`),start:values[`start${i}`],end:values[`end${i}`],pickupTime:values[`pickup${i}`],pickupAddress:values[`morningstop${i}`],returnAddress:values[`stop${i}`]}))};await api(values.id?`/students/${values.id}`:'/students',values.id?'PUT':'POST',record);}
 else if(action==='absence'){await api('/absences','POST',values);message='Abwesenheit übernommen. Wartende Fahrgäste aus Touren entfernt.';}
 else if(action==='school')await api(values.id?`/schools/${values.id}`:'/schools',values.id?'PUT':'POST',values);
 else if(action==='security'){await api('/security/setup','POST',values);config=await api('/config');message='Zugangspasswörter eingerichtet. Echtdatenimport ist freigegeben.';}
 else if(action==='bus'||action==='driver')await api((action==='bus'?'/buses':'/drivers')+(values.id?'/'+values.id:''),values.id?'PUT':'POST',{...values,active:data.has('active')});
 else if(action==='tour-create'){await api('/tours','POST',{date:selectedDate,direction,schoolId:values.schoolId,time:values.time,studentIds:data.getAll('studentIds')});message='Eigene Tour angelegt. Bitte Fahrzeug und Fahrer zuweisen.';}
 else if(action==='assignment')await api('/tours/assignment','POST',values);
 else if(action==='move')await api('/tours/move','POST',values);
 else if(action==='remove-absence'){await api('/absences/'+values.id,'DELETE',{});message='Abwesenheit zurückgenommen. Bitte Tourenzuordnung erneuern.';}
 else if(action==='plan'){const r=await api('/plan','POST',{date:selectedDate,direction});message=`${r.planned} Touren zusammengestellt${r.unassigned?' · '+r.unassigned+' Zuweisungen offen':''}`;}
 else if(action==='import'){const r=await api('/import/commit','POST',{token:preview.token,confirm:data.has('confirm'),schoolMappings:Object.fromEntries([...data.entries()].filter(([k])=>k.startsWith('mapping:')).map(([k,v])=>[k.slice(8),v]))});message=r.restored?'Backup wiederhergestellt':`${r.added} Schüler importiert, ${r.updated} aktualisiert`;page='students';config=await api('/config');}
 modal.close();await refresh(true);toast(message);
 }catch(error){errorEl.textContent=error.message;submit.disabled=false;}});

async function init(){try{config=await api('/config');selectedDate=config.today;while(dayIndex(selectedDate)>4)selectedDate=addDate(selectedDate,1);try{me=await api('/me');}catch{}if(me){if(location.pathname==='/fahrer')page='driver';await refresh(true);}else renderLogin();}catch{app.innerHTML='<div class="empty">Die App ist nicht erreichbar. Server starten und Seite neu laden.</div>';}}
await init();setInterval(()=>{if(me&&!document.hidden)refresh();},5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&me)refresh(true);});
